  const glossary = [
    ['Amplitud','Cantidad matemática que participa en la descripción cuántica; puede contener fase.','Cuántica'],
    ['Átomo','Sistema de un núcleo y electrones descritos por estados cuánticos.','Materia'],
    ['Campo','Descripción de una magnitud física en cada punto del espacio y el tiempo.','Física clásica'],
    ['Carga eléctrica','Propiedad que determina la interacción electromagnética de una partícula.','Electromagnetismo'],
    ['Cuantización','Restricción de ciertas magnitudes a valores permitidos discretos.','Cuántica'],
    ['Dualidad onda-partícula','El comportamiento cuántico puede mostrar detecciones localizadas y patrones de interferencia.','Cuántica'],
    ['Efecto fotoeléctrico','Emisión de electrones de un material al absorber fotones suficientemente energéticos.','Luz y materia'],
    ['Energía','Magnitud que permite describir transformaciones y cambios de un sistema.','Física'],
    ['Entrelazamiento','Estado conjunto cuyas correlaciones no se describen como estados independientes.','Cuántica'],
    ['Espín','Propiedad cuántica intrínseca de las partículas.','Cuántica'],
    ['Espectro electromagnético','Conjunto de las radiaciones electromagnéticas, ordenadas por frecuencia o longitud de onda.','Luz'],
    ['Fotón','Cuanto de la radiación electromagnética.','Cuántica'],
    ['Frecuencia','Número de ciclos por segundo de una oscilación u onda; se mide en Hz.','Ondas'],
    ['Función de onda','Representación matemática de un estado cuántico.','Cuántica'],
    ['Interferencia','Combinación de ondas o amplitudes que puede reforzar o reducir un resultado.','Ondas y cuántica'],
    ['Longitud de onda','Distancia entre puntos consecutivos equivalentes de una onda.','Ondas'],
    ['Método científico','Proceso flexible de preguntas, hipótesis, pruebas, observación y revisión.','Ciencia'],
    ['Orbital','Estado cuántico de un electrón en un átomo; no es una órbita planetaria.','Átomos'],
    ['Principio de incertidumbre','Límite fundamental para la dispersión simultánea de ciertos pares de magnitudes.','Cuántica'],
    ['Probabilidad','Medida de qué tan posible es un resultado, según un modelo y sus condiciones.','Ciencia'],
    ['Superposición','Combinación coherente de estados cuánticos.','Cuántica'],
    ['Velocidad de la luz','En el vacío, c = 299 792 458 m/s.','Relatividad'],
    ['QED','Electrodinámica cuántica: teoría cuántica de la interacción entre luz y partículas cargadas.','Electrodinámica'],
    ['Fotón virtual','Línea interna de ciertos cálculos perturbativos; no es una partícula libre que necesariamente se detecte directamente.','QED'],
    ['Fotón real','Cuanto electromagnético que puede propagarse como estado externo y ser absorbido o detectado.','QED'],
    ['Intensidad','Energía transportada por radiación por unidad de área y tiempo; no equivale a energía por fotón.','Luz'],
    ['Polarización','Propiedad de una onda electromagnética ligada a la orientación y evolución de su campo eléctrico.','Luz'],
    ['Vértice QED','Elemento de interacción que conecta el campo cargado con el campo electromagnético en un diagrama.','QED'],
    ['Renormalización','Procedimiento técnico de la teoría cuántica de campos para relacionar parámetros con observables y producir predicciones finitas.','QED'],
    ['Constante de estructura fina','Parámetro adimensional α que caracteriza la intensidad del acoplamiento electromagnético.','QED'],
    ['Incertidumbre experimental','Cuantificación de la precisión y dispersión asociada a un resultado de medición.','Ciencia']
  ];

  const defaultSettings = { sound:true, animations:true, theme:'dark' };
  const defaultSave = () => ({
    version:SAVE_VERSION, xp:0, points:0, completedLessons:[], visitedLessons:[], discoveredConcepts:[], completedActivities:[], startedActivities:[], achievements:[], formulasStudied:[], diagramsUnlocked:[], reviewConcepts:[], notes:{}, quizHistory:[], examHistory:[],
    settings:{...defaultSettings}, lastLesson:'physics-method', createdAt:Date.now(), lastPlayedAt:Date.now()
  });

  function loadSave() {
    try {
      const raw = localStorage.getItem(SAVE_KEY);
      if (!raw) return defaultSave();
      const parsed = JSON.parse(raw);
      if (!parsed || typeof parsed !== 'object') return defaultSave();
      const base = defaultSave();
      const arrayKeys = ['completedLessons','visitedLessons','discoveredConcepts','completedActivities','startedActivities','achievements','formulasStudied','diagramsUnlocked','reviewConcepts'];
      for (const key of arrayKeys) if (Array.isArray(parsed[key])) base[key] = [...new Set(parsed[key].filter(v => typeof v === 'string'))];
      for(const key of ['quizHistory','examHistory'])if(Array.isArray(parsed[key]))base[key]=parsed[key].filter(v=>v&&typeof v==='object').slice(-1000);
      if(parsed.notes&&typeof parsed.notes==='object')base.notes=Object.fromEntries(Object.entries(parsed.notes).filter(([k,v])=>typeof k==='string'&&typeof v==='string').slice(0,100).map(([k,v])=>[k,v.slice(0,2000)]));
      base.xp = Number.isFinite(parsed.xp) && parsed.xp >= 0 ? Math.floor(parsed.xp) : 0;
      base.points = Number.isFinite(parsed.points) && parsed.points >= 0 ? Math.floor(parsed.points) : base.xp;
      base.lastLesson = lessons.some(l => l.id === parsed.lastLesson) ? parsed.lastLesson : 'physics-method';
      base.createdAt = Number.isFinite(parsed.createdAt) ? parsed.createdAt : Date.now();
      base.lastPlayedAt = Date.now();
      if (parsed.settings && typeof parsed.settings === 'object') {
        base.settings.sound = typeof parsed.settings.sound === 'boolean' ? parsed.settings.sound : true;
        base.settings.animations = typeof parsed.settings.animations === 'boolean' ? parsed.settings.animations : true;
        base.settings.theme = parsed.settings.theme === 'light' ? 'light' : 'dark';
      }
      return base;
    } catch (error) {
      console.warn('No se pudo leer el guardado; se inicia con valores seguros.', error);
      return defaultSave();
    }
  }

  let save = loadSave();
