  function worldLessons(worldId) { return lessons.filter(l => l.worldId === worldId); }
  function completedCount(worldId) { return worldLessons(worldId).filter(l => save.completedLessons.includes(l.id)).length; }
  function worldPercent(worldId) { const list = worldLessons(worldId); return list.length ? completedCount(worldId) / list.length * 100 : 0; }
  function isWorldUnlocked(worldId) {
    if (worldId === 'world-rules') return true;
    if (worldId === 'world-quantum') return worldPercent('world-rules') >= 70;
    if (worldId === 'world-light-matter') return worldPercent('world-quantum') >= 70;
    if (worldId === 'world-qed') return worldPercent('world-light-matter') >= 70;
    if (worldId === 'world-feynman') return worldPercent('world-qed') >= 70;
    if (worldId === 'world-beyond-light') return worldPercent('world-feynman') >= 70;
    if (worldId === 'world-math') return worldPercent('world-beyond-light') >= 70;
    if (worldId === 'world-frontier') return worldPercent('world-math') >= 70;
    return false;
  }
  function discoveredCount() { return save.discoveredConcepts.length; }
  function lessonById(id) { return lessons.find(l => l.id === id); }
  function worldById(id) { return worlds.find(w => w.id === id); }
  function selectedLesson() { return lessonById(ui.lessonId) || lessonById(save.lastLesson) || lessons[0]; }
  function getContinueLesson() {
    const last = lessonById(save.lastLesson);
    if (last && isWorldUnlocked(last.worldId) && !save.completedLessons.includes(last.id)) return last;
    for (const world of worlds.filter(w => w.built && isWorldUnlocked(w.id))) {
      const next = worldLessons(world.id).find(l => !save.completedLessons.includes(l.id));
      if (next) return next;
    }
    return lessons[0];
  }
  function recordConcepts(list) {
    let changed = false;
    list.forEach(word => { const normalized = String(word); if (!save.discoveredConcepts.includes(normalized)) { save.discoveredConcepts.push(normalized); changed = true; } });
    if (changed) persist();
  }
  const achievementDefinitions = [
    {id:'first-lesson',icon:'✦',title:'Primera chispa',description:'Completa tu primera lección.',test:() => save.completedLessons.length >= 1},
    {id:'five-lessons',icon:'✧',title:'Curiosidad en marcha',description:'Completa cinco lecciones.',test:() => save.completedLessons.length >= 5},
    {id:'ten-concepts',icon:'▤',title:'Cuaderno abierto',description:'Descubre diez conceptos.',test:() => save.discoveredConcepts.length >= 10},
    {id:'world-one',icon:'⌘',title:'Explorador clásico',description:'Completa todas las lecciones del mundo 1.',test:() => completedCount('world-rules') === worldLessons('world-rules').length},
    {id:'atom-builder',icon:'◉',title:'Arquitecto de átomos',description:'Registra tu experimento con el constructor de átomos.',test:() => save.completedActivities.includes('atom-builder')},
    {id:'slit-lab',icon:'∿',title:'Patrón revelado',description:'Registra al menos 30 detecciones en doble rendija.',test:() => save.completedActivities.includes('double-slit-30')},
    {id:'quantum-world',icon:'◈',title:'Tras la puerta',description:'Completa todas las lecciones de la puerta cuántica.',test:() => completedCount('world-quantum') === worldLessons('world-quantum').length && isWorldUnlocked('world-quantum')}
    ,{id:'final-master',icon:'⌬',title:'Maestro de la QED',description:'Obtén al menos 8 aciertos en el examen final.',test:() => save.examHistory.some(h=>h.total===finalQuestions.length&&h.score>=8)}
  ];
  function refreshAchievements() {
    let earned = [];
    achievementDefinitions.forEach(a => { if (a.test() && !save.achievements.includes(a.id)) { save.achievements.push(a.id); earned.push(a); } });
    if (earned.length) { persist(); earned.forEach(a => notify(`Logro desbloqueado: ${a.title}`)); playTone(true); }
  }

  function renderHome() {
    const continueLesson = getContinueLesson();
    const w1 = worldPercent('world-rules'); const w2 = worldPercent('world-quantum');
    const totalAvailable = lessons.filter(l => isWorldUnlocked(l.worldId)).length;
    const totalCompleted = lessons.filter(l => isWorldUnlocked(l.worldId) && save.completedLessons.includes(l.id)).length;
    return `
      <section class="hero">
        <div class="hero-copy">
          <p class="eyebrow"><span class="eyebrow-dot"></span> TU VIAJE COMIENZA AQUÍ</p>
          <h1>El universo es extraño.<br><span>Vamos a entenderlo.</span></h1>
          <p class="lead">Explora la física desde sus reglas más simples hasta las ideas que cambiaron nuestra forma de mirar la realidad. Pregunta, experimenta y construye tu propio cuaderno científico.</p>
          <div class="hero-actions">
            <button class="btn btn-primary" data-action="continue">${save.completedLessons.length ? '▶ Continuar exploración' : '▶ Comenzar aventura'} <span aria-hidden="true">→</span></button>
            <button class="btn btn-secondary" data-action="worlds">◎ Explorar los mundos</button>
            <button class="btn btn-quiet" data-action="new-game">Nueva partida ↺</button>
          </div>
        </div>
        <div class="hero-art" aria-hidden="true"><div class="hero-planet"><span class="planet-core"></span><i class="hero-electron"></i><b class="hero-orbit-dot"></b></div><div class="hero-tag">FÍSICA · CURIOSIDAD · QED</div></div>
      </section>
      <section class="stats-grid" aria-label="Tu progreso">
        <div class="stat-card"><div class="stat-top">Experiencia <span class="stat-icon">✦</span></div><div class="stat-value">${save.xp}</div><div class="stat-note">puntos de conocimiento (XP)</div></div>
        <div class="stat-card"><div class="stat-top">Lecciones <span class="stat-icon">▤</span></div><div class="stat-value">${totalCompleted}<span class="muted" style="font-size:14px;font-weight:600"> / ${totalAvailable}</span></div><div class="stat-note">completadas en los mundos disponibles</div></div>
        <div class="stat-card"><div class="stat-top">Conceptos <span class="stat-icon">◇</span></div><div class="stat-value">${discoveredCount()}</div><div class="stat-note">registrados en tu cuaderno</div></div>
        <div class="stat-card"><div class="stat-top">Logros <span class="stat-icon">⌑</span></div><div class="stat-value">${save.achievements.length}<span class="muted" style="font-size:14px;font-weight:600"> / ${achievementDefinitions.length}</span></div><div class="stat-note">hitos de tu exploración</div></div>
      </section>
      <div class="home-grid">
        <section class="panel">
          <div class="panel-title-row"><div><h3>Tu mapa de progreso</h3><p class="muted small" style="margin:4px 0 0">Cada concepto abre una nueva pregunta.</p></div><button class="btn btn-quiet btn-small" data-action="worlds">Ver mapa ↗</button></div>
          ${worlds.filter(w => w.built).map(w => `<div class="world-progress-line"><div class="world-small-icon">${w.icon}</div><div class="grow"><strong>${escapeHTML(w.title)}</strong><p>${completedCount(w.id)} de ${worldLessons(w.id).length} lecciones completadas</p><div class="mini-progress"><span style="width:${worldPercent(w.id)}%"></span></div></div><span class="progress-percent">${formatPercent(worldPercent(w.id))}</span></div>`).join('')}
          <div class="world-progress-line"><div class="world-small-icon" style="opacity:.55">✧</div><div class="grow"><strong>8 mundos de exploración</strong><p>La ruta completa hasta la frontera del conocimiento.</p><div class="mini-progress"><span style="width:${lessons.length?save.completedLessons.length/lessons.length*100:0}%"></span></div></div><span class="progress-percent">${Math.round(lessons.length?save.completedLessons.length/lessons.length*100:0)}%</span></div>
        </section>
        <section class="feature-card"><div class="feature-kicker">LABORATORIO DESTACADO</div><h3>¿Partícula o patrón de onda?</h3><div class="feature-art" aria-hidden="true"><i class="feature-nucleus"></i><b class="feature-electron"></b></div><p>Dispara partículas una a una, observa dónde aparecen y compara cómo cambia el patrón cuando abres las rendijas.</p><button class="btn btn-primary" data-action="open-slit">Entrar al laboratorio →</button><p class="micro" style="margin:13px 0 0">Disponible al desbloquear el mundo 2.</p></section>
      </div>
      <div class="section-head"><div><h2>Retoma el hilo</h2><p>El mejor laboratorio siempre empieza con una buena pregunta.</p></div></div>
      <section class="panel" style="display:flex;align-items:center;gap:15px;flex-wrap:wrap"><div class="world-small-icon" style="width:52px;height:52px;font-size:23px">${worldById(continueLesson.worldId).icon}</div><div class="grow"><span class="eyebrow" style="margin-bottom:5px">MUNDO ${String(worldById(continueLesson.worldId).number).padStart(2,'0')} · ${continueLesson.level.toUpperCase()}</span><h3 style="margin:0 0 4px">${escapeHTML(continueLesson.title)}</h3><p class="muted small" style="margin:0">${escapeHTML(continueLesson.explanation.slice(0,125))}…</p></div><button class="btn btn-secondary" data-action="open-lesson" data-id="${continueLesson.id}">Abrir lección →</button></section>
      <div class="section-head"><div><h2>Una nota antes de entrar</h2><p>La curiosidad es una herramienta más potente que fingir saberlo todo.</p></div></div>
      <div class="notice"><span class="notice-icon">✦</span><div><strong>Inspirado en la forma de pensar de Richard Feynman.</strong> Qubit Quest es un proyecto educativo original; no sustituye un curso formal ni reproduce experimentos reales con exactitud completa. Sus simulaciones simplifican los modelos para hacerlos explorables.</div></div>
    `;
  }

  function renderWorlds() {
    return `<p class="eyebrow"><span class="eyebrow-dot"></span> MAPA DE EXPLORACIÓN</p><h1>Ocho mundos.<br><span class="highlight">Una pregunta enorme.</span></h1><p class="lead">Completa al menos el 70% de cada ruta para desbloquear la siguiente. La frontera científica distingue resultados establecidos de preguntas abiertas.</p>
      <div class="section-head"><div><h2>Ruta de aprendizaje</h2><p>Completa las lecciones para seguir avanzando.</p></div><span class="pill">${worlds.filter(w=>w.built).length} de 8 mundos · fase 4</span></div>
      <div class="world-grid">${worlds.map(w => {
        const unlocked = isWorldUnlocked(w.id); const list = worldLessons(w.id); const pct = list.length ? worldPercent(w.id) : 0;
        const status = !w.built ? 'Próximamente' : unlocked ? (pct >= 100 ? 'Completado' : 'Disponible') : 'Bloqueado';
        const previous = worlds.find(x=>x.number===w.number-1);
        const requirement = w.number===1 ? `${list.length} lecciones · actividades guiadas · evaluación breve` : `Requisito: completa el 70% de “${previous.title}” (${Math.ceil(worldLessons(previous.id).length*.7)} lecciones).`;
        return `<article class="world-card ${!unlocked?'locked':''}"><div class="world-card-head"><div><div class="world-number">MUNDO ${String(w.number).padStart(2,'0')} · ${w.subtitle.toUpperCase()}</div></div><div class="world-glyph">${w.icon}</div></div><h3>${escapeHTML(w.title)}</h3><p>${escapeHTML(w.description)}</p><div class="world-card-bottom"><div class="world-card-bottom-row"><span class="world-status ${!unlocked?'lock':''}">${status}</span><span class="muted">${w.built ? `${completedCount(w.id)} / ${list.length} lecciones` : 'Contenido no implementado'}</span></div>${w.built ? `<div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div>` : `<div class="progress-track"><div class="progress-fill" style="width:0"></div></div>`}<div class="world-card-bottom-row"><span class="micro">${escapeHTML(requirement)}</span>${w.built ? `<button class="btn ${unlocked?'btn-secondary':'btn-quiet'} btn-small" data-action="enter-world" data-id="${w.id}" ${!unlocked?'aria-label="Ver requisito de desbloqueo"':''}>${unlocked?'Entrar →':'Requisito ↗'}</button>` : `<span class="micro">Por diseñar</span>`}</div>${unlocked?`<button class="btn btn-quiet btn-small" data-action="start-world-exam" data-id="${w.id}">Evaluación del mundo →</button>`:''}</div></article>`;
      }).join('')}</div><section class="panel" style="margin-top:20px"><h2>Evaluación final: Maestro de la QED</h2><p>Combina luz, materia, amplitudes, diagramas, interacciones y contexto histórico. Puedes repetirla para comparar tus resultados.</p><button class="btn btn-primary" data-action="exam">Comenzar evaluación final →</button></section>`;
  }

  function openLesson(id) {
    const lesson = lessonById(id);
    if (!lesson) { notify('Esta lección aún no está disponible.'); return; }
    if (!isWorldUnlocked(lesson.worldId)) { notify('Completa el 70% del mundo anterior para abrir esta ruta.'); ui.screen='worlds'; render(); return; }
    const unmet=(lesson.prerequisites||[]).find(id=>!save.completedLessons.includes(id));if(unmet){notify(`Completa primero “${lessonById(unmet).title}” para abrir este módulo.`);ui.screen='worlds';render();return;}
    ui.lessonId = lesson.id; ui.screen = 'lesson'; ui.quizStarted = false; ui.quizIndex = 0; ui.quizAnswers = []; ui.quizFeedback = null; ui.quizFinished = false; ui.activityStep = 0;
    save.lastLesson = lesson.id; if(!save.visitedLessons.includes(lesson.id))save.visitedLessons.push(lesson.id);
    const formulaNotes={'amplitudes-probabilities':'Probabilidad P=|A|²','photons-photoelectric':'E=hν','quantum-energy':'ΔE=hν','math-action-schrodinger':'S=∫L dt; fase exp(iS/ℏ)','math-operators-expectations':'⟨A⟩=⟨ψ|A|ψ⟩','math-functions-complex':'|a+bi|²=a²+b²'};
    if(formulaNotes[lesson.id]&&!save.formulasStudied.includes(formulaNotes[lesson.id]))save.formulasStudied.push(formulaNotes[lesson.id]);recordConcepts(lesson.keys); persist(); render();
  }
  function illustrationKind(lesson) {
    const id=lesson.id;
    if(['matter-atoms','subatomic-particles','orbitals'].includes(id)) return id==='orbitals'?'orbital':'atom';
    if(id==='double-slit') return 'slit';
    if(['waves-frequency','electromagnetic-spectrum','wave-particle'].includes(id)) return 'wave';
    if(['electric-charge','forces-fields','electricity-magnetism'].includes(id)) return 'field';
    if(['energy-conservation','quantum-energy','photons-photoelectric','speed-of-light'].includes(id)) return 'photon';
    if(['quantization','quantum-states'].includes(id)) return 'levels';
    if(['superposition','wavefunction','quantum-probability','amplitudes-probabilities','measurement'].includes(id)) return 'amplitude';
    if(['uncertainty'].includes(id)) return 'uncertainty';
    if(['spin','entanglement'].includes(id)) return id;
    if(['notation-units','special-relativity'].includes(id)) return 'notation';
    if(['physics-method','scientific-method','classical-modern'].includes(id)) return 'method';
    if(lesson.worldId==='world-feynman') return 'paths';
    if(lesson.worldId==='world-beyond-light') return 'particles';
    if(lesson.worldId==='world-math') return 'math';
    return 'generic';
  }
